export function scan(root){const list=[];function walk(rel=''){for(const name of fs.readdirSync(path.join(root,rel)).sort()){const r=path.posix.join(rel,name),p=path.join(root,r),s=fs.lstatSync(p);assert(!s.isSymbolicLink(),'Symlink in inventory');if(s.isDirectory())walk(r);else{assert(s.isFile()&&s.size<=64*1024*1024);assert(list.length<2048);list.push([r,s.size,hash(fs.readFileSync(p))]);}}}walk();return list;}
export function corpus(root){const list=scan(root),m=JSON.parse(fs.readFileSync(root+'/manifest.json'));assert.equal(list.length,626);assert.equal(m.articles.length,199);assert.equal(Object.keys(m.files).length,625);assert.deepEqual(list.map(x=>x[0]).sort(),['manifest.json',...Object.keys(m.files)].sort());for(const[p,,h]of list)if(p!=='manifest.json')assert.equal(m.files[p],h);return{files:list,descriptor:{manifest_sha256:hash(fs.readFileSync(root+'/manifest.json')),corpus_sha256:hash(Buffer.from(json(list))),corpus_revision:m.revision,articles:199,listed_sha_files:625,files_including_manifest:626,bytes_including_manifest:list.reduce((n,x)=>n+x[1],0),png_files:list.filter(x=>x[0].toLowerCase().endsWith('.png')).length}};}
export function checkAudits(source,consumer,c){assert.equal(source.result,'passed');assert.equal(source.profile,'published-library');assert.equal(source.revision,c.corpus_revision);assert.equal(source.articles.length,199);assert.equal(source.checked_files,625);assert.equal(consumer.status,'passed');assert.equal(consumer.validator,'app-ContentValidator');for(const[k,v]of Object.entries({revision:c.corpus_revision,articles:199,files_including_manifest:626,verified_files_excluding_manifest:625,PNG_files:c.png_files,bytes_including_manifest:c.bytes_including_manifest}))assert.equal(consumer[k],v,'Consumer descriptor mismatch '+k);}
function git(repo,args){assert(['rev-parse','show','ls-tree','ls-files'].includes(args[0]));return execFileSync('/usr/bin/git',['-C',repo,...args],{env:{...process.env,GIT_NO_LAZY_FETCH:'1',GIT_OPTIONAL_LOCKS:'0',GIT_TERMINAL_PROMPT:'0',GIT_NO_REPLACE_OBJECTS:'1'},timeout:10000,maxBuffer:16*1024*1024});}
export function freeze(repo,work,expected){assert.match(expected,/^[0-9a-f]{40}$/);assert.equal(git(repo,['rev-parse','HEAD']).toString().trim(),expected);const tree=git(repo,['rev-parse',expected+'^{tree}']).toString().trim();assert.match(tree,/^[0-9a-f]{40}$/);const tracked=git(repo,['ls-files','-z','--',...Object.keys(FIXED8),...SOURCE4,...INPUT_DEPENDENCIES6,'ios/AILibraryTests/SearchIndexTests.swift','scripts/build-ios-native-content.mjs','scripts/lib/ios-native-content.mjs','ios/tools','package.json','package-lock.json','ios/tests/PackageAudit.swift','ios/tests/native-content-audit.mjs','ios/tests/check-package.sh']).toString().split('\0').filter(Boolean);assert(tracked.length<=1024);const files={};for(const p of tracked.sort()){assert(!p.split('/').includes('..'));const f=path.join(repo,p),s=fs.lstatSync(f);assert(s.isFile()&&!s.isSymbolicLink());const b=fs.readFileSync(f),frozen=git(repo,['show',expected+':'+p]);assert(b.equals(frozen),'Working source differs from immutable commit '+p);files[p]={bytes:b.length,sha256:hash(b),mode:s.mode&0o777};}for(const[p,want]of Object.entries(FIXED8))assert.equal(files[p]?.sha256,want,'Fixed Core8 changed '+p);for(const p of [...SOURCE4,...INPUT_DEPENDENCIES6])assert(files[p],'Missing mandatory tracked input '+p);const pkg=JSON.parse(fs.readFileSync(repo+'/package.json'));assert.equal(pkg.scripts['ios:benchmark:core'],'bash ios/tests/check-core-performance.sh');assert(!('preios:benchmark:core'in pkg.scripts)&&!('postios:benchmark:core'in pkg.scripts));const expectedShell='#!/bin/bash\nset -euo pipefail\n# No implicit compilation or benchmark execution. The Node CLI requires --run.\nscript_root="$(cd "$(dirname "$0")" && pwd)"\nexec "${NODE_BINARY:-node}" "$script_root/core-performance-runner.mjs" "$@"\n';assert.equal(fs.readFileSync(repo+'/ios/tests/check-core-performance.sh','utf8'),expectedShell,'Alias expansion source changed');const inventory=corpus(repo+'/ios/AILibrary/Content');checkAudits(JSON.parse(fs.readFileSync(work+'/source-audit.json')),JSON.parse(fs.readFileSync(work+'/consumer-audit.json')),inventory.descriptor);const capture=JSON.parse(fs.readFileSync(work+'/host-capture.json'));assert.equal(capture.Xcode,'16.4');assert.equal(capture.Xcode_build,'16F6');assert.equal(capture.SDK,'15.5');assert.equal(capture.architecture,'arm64');assert.match(capture.macOS,/^15\./);assert.match(capture.Node,/^v24\./);const manifest={schema_version:1,source_head:expected,source_tree:tree,files,production_source4:Object.fromEntries(SOURCE4.map(p=>[p,files[p].sha256])),LibraryCoreTests_in_source4:false,corpus:inventory.descriptor,corpus_files:inventory.files,host_capture:capture,entry:{npm_alias:pkg.scripts['ios:benchmark:core'],mode:'validated-alias-equivalent-direct-Node; npm wrapper not executed',Node:capture.Node_binary,script:repo+'/ios/tests/core-performance-runner.mjs'},historical_b79_statistics:'history only; not comparable to this new Hosted profile',adopted_budget:null};fs.writeFileSync(work+'/input-manifest.json',json(manifest),{flag:'wx',mode:0o444});return manifest;}
export function verify(repo,work){const m=JSON.parse(fs.readFileSync(work+'/input-manifest.json'));assert.equal(git(repo,['rev-parse','HEAD']).toString().trim(),m.source_head);assert.equal(git(repo,['rev-parse',m.source_head+'^{tree}']).toString().trim(),m.source_tree);for(const[p,v]of Object.entries(m.files)){const info=fs.lstatSync(repo+'/'+p);assert(info.isFile()&&!info.isSymbolicLink());assert.equal(info.mode&0o777,v.mode);const b=fs.readFileSync(repo+'/'+p);assert.equal(b.length,v.bytes);assert.equal(hash(b),v.sha256);}const now=corpus(repo+'/ios/AILibrary/Content');assert.deepEqual(now.descriptor,m.corpus);assert.deepEqual(now.files,m.corpus_files);fs.writeFileSync(work+'/after-freeze.json',json({source_and_corpus_unchanged:true,input_manifest_SHA256:hash(fs.readFileSync(work+'/input-manifest.json')),source_head:m.source_head,source_tree:m.source_tree}),{flag:'wx'});return true;}
export function stage(work,target){assert(!fs.existsSync(target));fs.mkdirSync(target,{mode:0o700});const all=scan(work),allowed=all.filter(([p])=>!p.includes('/')||/^results\/(?:\d\d-[a-z-]+-\d\.(?:json|stderr\.txt)|identity\.json|summary\.json|compiler\.stderr\.txt)$/.test(p));const max=8*1024*1024,total=allowed.reduce((n,x)=>n+x[1],0);const inventory={files:allowed,excluded_metadata:all.filter(([p])=>!allowed.some(([a])=>a===p)),total_bytes:total,limit_bytes:max,complete_copy:false,never_merge:true};inventory.complete_copy=total+Buffer.byteLength(json(inventory))<=max;fs.writeFileSync(target+'/artifact-inventory.json',json(inventory));assert(inventory.complete_copy,'Evidence oversized; inventory retained, no partial success');for(const[p]of allowed){const t=path.join(target,p);fs.mkdirSync(path.dirname(t),{recursive:true});fs.copyFileSync(path.join(work,p),t,fs.constants.COPYFILE_EXCL);}assert(scan(target).reduce((n,x)=>n+x[1],0)<=max);return inventory;}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){try{const[mode,repo,work,extra]=process.argv.slice(2);if(mode==='freeze')freeze(repo,work,extra);else if(mode==='verify')verify(repo,work);else if(mode==='stage')stage(repo,work);else throw Error('Unknown evidence mode');}catch(e){console.error('Core Hosted evidence refused: '+e.message);process.exitCode=1;}}
